const item = $input.first();
const b64 = item.binary?.data?.data || '';
const body = $node['Webhook CMS'].json.body || $node['Webhook CMS'].json;

return {
  name: body.name || 'Calzado',
  price: body.price || '',
  payload: {
    contents: [{
      parts: [
        {
          text: `Professional high-end fashion editorial photoshoot of a model wearing this exact footwear: ${body.name}. Photorealistic 8k, Vogue magazine style, studio dramatic lighting, elegant pose, perfectly integrated footwear.`
        },
        {
          inlineData: {
            mimeType: 'image/jpeg',
            data: b64
          }
        }
      ]
    }]
  }
};

// Extrae el resultado Base64 generado por Google Nano Banana
const res = $input.first().json;
const parts = res.candidates?.[0]?.content?.parts || [];
let generatedB64 = '';
for (const p of parts) {
  if (p.inlineData?.data) {
    generatedB64 = p.inlineData.data;
    break;
  }
}

return {
  has_image: Boolean(generatedB64),
  generated_base64: generatedB64
};
